    l--;
    r--;

    set<int> usedLettersSet;
    int minUniqueLetters = 26;

    for (int startCharIdx = 0; startCharIdx < 26; startCharIdx++) {
        for (int repeatCharIdx = a; repeatCharIdx < 26; repeatCharIdx++) {
            string currentString = basePattern;
